#!/usr/bin/env python3
"""Offline batch normalization pipeline.

Scans dropbox/ recursively, validates records, and writes:

    normalized/<record_type>_<record_id>.json   (one file per accepted record)
    index.csv
    reject_ledger.csv
    batch_summary.json

The run is a pure function of the input tree: inputs are only read, outputs are
rebuilt from scratch, and every ordering decision is explicit, so re-running is
idempotent.

Usage:
    python3 normalize.py            # build outputs
    python3 normalize.py --dry-run  # validate only, print nothing to disk
"""

from __future__ import annotations

import argparse
import csv
import io
import json
import math
import os
import shutil
import sys
from pathlib import Path

WORKSPACE = Path(__file__).resolve().parent
DROPBOX = WORKSPACE / "dropbox"
RULES_PATH = WORKSPACE / "normalization_rules.yaml"
NORMALIZED = WORKSPACE / "normalized"
INDEX_PATH = WORKSPACE / "index.csv"
REJECT_PATH = WORKSPACE / "reject_ledger.csv"
SUMMARY_PATH = WORKSPACE / "batch_summary.json"

# ---------------------------------------------------------------- rules ----

def load_rules(path: Path) -> dict:
    """Minimal reader for the flat YAML subset used by normalization_rules.yaml.

    Supports `key: [a, b, c]` and `key: "value"` lines only, which is all the
    rules file uses. Falls back to the documented defaults if the file is
    absent so the pipeline stays offline and dependency free.
    """
    rules = {
        "statuses": ["active", "inactive", "open", "closed", "pending"],
        "currencies": ["USD", "EUR"],
        "output_name": "{record_type}_{record_id}.json",
    }
    if not path.is_file():
        return rules
    text = path.read_text(encoding="utf-8")
    for raw in text.splitlines():
        line = raw.split("#", 1)[0].strip()
        if not line or ":" not in line:
            continue
        key, value = line.split(":", 1)
        key, value = key.strip(), value.strip()
        if value.startswith("[") and value.endswith("]"):
            items = [v.strip().strip("'\"") for v in value[1:-1].split(",")]
            rules[key] = [v for v in items if v]
        elif len(value) >= 2 and value[0] == value[-1] and value[0] in "'\"":
            rules[key] = value[1:-1]
        elif value:
            rules[key] = value
    return rules


RULES = load_rules(RULES_PATH)
STATUSES = list(RULES["statuses"])
OUTPUT_NAME = str(RULES["output_name"])

ERROR_TYPES = (
    "unsupported_extension",
    "malformed_file",
    "missing_required_field",
    "invalid_status",
    "invalid_amount",
    "duplicate_record_id",
)

SUPPORTED_EXTENSIONS = {".csv": "customer", ".json": "order", ".txt": "note"}

# Formatters keep amounts as JSON numbers: 88 stays 88, 120.5 stays 120.5.
# ------------------------------------------------------------- helpers ----


def rel(path: Path) -> str:
    """Workspace-relative POSIX path, e.g. dropbox/customers/customers_01.csv."""
    return path.relative_to(WORKSPACE).as_posix()


def blank(value) -> bool:
    return not isinstance(value, str) or value.strip() == ""


def safe_record_id(record_id: str) -> bool:
    """Guards the output filename against separators / traversal / NUL."""
    return bool(record_id) and not any(
        ch in record_id for ch in ("/", "\\", "\0")
    ) and record_id not in (".", "..")


def output_filename(record_type: str, record_id: str) -> str:
    name = OUTPUT_NAME.format(record_type=record_type, record_id=record_id)
    # Defensive: keep the generated name a single path component.
    if Path(name).name != name:
        raise ValueError(f"output_name produced an unsafe filename: {name!r}")
    return name


class Rejected(Exception):
    def __init__(self, error_type: str, details: str):
        assert error_type in ERROR_TYPES, error_type
        super().__init__(details)
        self.error_type = error_type
        self.details = details


def reject(source_path: str, error_type: str, details: str) -> dict:
    return {
        "source_path": source_path,
        "error_type": error_type,
        "details": details,
    }


# ------------------------------------------------------------- readers -----

def read_text(path: Path) -> str:
    try:
        raw = path.read_bytes()
    except OSError as exc:
        raise Rejected("malformed_file", f"unreadable file: {exc.strerror}")
    try:
        return raw.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise Rejected("malformed_file", "file is not valid UTF-8 text")


def parse_customers(path: Path, source_path: str) -> list[dict]:
    """CSV with columns id,name,email,status -> customer records."""
    text = read_text(path)
    try:
        reader = csv.DictReader(io.StringIO(text, newline=""))
        fieldnames = reader.fieldnames
        if not fieldnames:
            raise Rejected("malformed_file", "CSV has no header row")
        header = [(name or "").strip().lower() for name in fieldnames]
        required = ["id", "name", "email", "status"]
        missing_cols = [col for col in required if col not in header]
        if missing_cols:
            raise Rejected(
                "malformed_file",
                "CSV header missing column(s): " + ",".join(missing_cols),
            )
        # Map normalised header name -> actual column index/name.
        column = {}
        for col in required:
            column[col] = fieldnames[header.index(col)]

        rows = list(reader)
    except csv.Error as exc:
        raise Rejected("malformed_file", f"unparsable CSV: {exc}")

    records = []
    for lineno, row in enumerate(rows, start=2):
        values = {col: row.get(column[col]) for col in required}
        values = {
            col: (val.strip() if isinstance(val, str) else val)
            for col, val in values.items()
        }
        for col in required:
            if blank(values[col]):
                raise_record = Rejected(
                    "missing_required_field", f"missing required field: {col}"
                )
                records.append({"reject": raise_record})
                break
        else:
            status = values["status"]
            if status not in STATUSES:
                records.append(
                    {"reject": Rejected("invalid_status", f"invalid status: {status}")}
                )
            else:
                records.append(
                    {
                        "record": {
                            "record_id": values["id"],
                            "record_type": "customer",
                            "name": values["name"],
                            "email": values["email"],
                            "status": status,
                        }
                    }
                )
    return records


def parse_orders(path: Path, source_path: str) -> list[dict]:
    """JSON object with order_id, customer_id, amount, currency -> order record."""
    text = read_text(path)
    try:
        payload = json.loads(text)
    except json.JSONDecodeError as exc:
        raise Rejected(
            "malformed_file", f"invalid JSON: {exc.msg} (line {exc.lineno} column {exc.colno})"
        )
    if not isinstance(payload, dict):
        raise Rejected("malformed_file", "JSON top level is not an object")

    outliers = []
    required = ["order_id", "customer_id", "amount", "currency"]
    values = {}
    for key in required:
        value = payload.get(key)
        values[key] = value.strip() if isinstance(value, str) else value

    missing = [key for key in required if key == "amount" and key not in payload]
    if "amount" not in payload:
        return [{"reject": Rejected("missing_required_field", "missing required field: amount")}]
    for key in ("order_id", "customer_id", "currency"):
        if blank(values[key]):
            return [
                {
                    "reject": Rejected(
                        "missing_required_field", f"missing required field: {key}"
                    )
                }
            ]

    amount = payload.get("amount")
    if isinstance(amount, bool) or not isinstance(amount, (int, float)):
        return [
            {
                "reject": Rejected(
                    "invalid_amount",
                    f"amount is not a JSON number: {json.dumps(amount)}",
                )
            }
        ]
    if not math.isfinite(amount) or amount <= 0:
        return [
            {
                "reject": Rejected(
                    "invalid_amount", f"amount must be a positive finite number: {amount}"
                )
            }
        ]

    if not safe_record_id(str(values["order_id"])):
        return [{"reject": Rejected("malformed_file", "unsafe order_id value")}]

    return [
        {
            "record": {
                "record_id": values["order_id"],
                "record_type": "order",
                "customer_id": values["customer_id"],
                "amount": amount,
                "currency": values["currency"],
                "status": "active",
            }
        }
    ]


def parse_notes(path: Path, source_path: str) -> list[dict]:
    """TXT with `Case: ...`, `Owner: ...`, `Status: ...` lines -> note record."""
    text = read_text(path)
    fields = {}
    for lineno, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line:
            continue
        if ":" not in line:
            raise Rejected("malformed_file", f"line {lineno} is not 'Key: value'")
        key, value = line.split(":", 1)
        key = key.strip().lower()
        value = value.strip()
        if key in ("case", "owner", "status") and key in fields:
            raise Rejected("malformed_file", f"duplicate line for field: {key}")
        fields[key] = value

    for key, label in (("case", "Case"), ("owner", "Owner"), ("status", "Status")):
        if blank(fields.get(key)):
            return [
                {
                    "reject": Rejected(
                        "missing_required_field", f"missing required field: {label}"
                    )
                }
            ]

    status = fields["status"]
    if status not in STATUSES:
        return [{"reject": Rejected("invalid_status", f"invalid status: {status}")}]

    case_id = fields["case"]
    if not safe_record_id(case_id):
        return [{"reject": Rejected("malformed_file", "unsafe Case value")}]

    return [
        {
            "record": {
                "record_id": case_id,
                "record_type": "note",
                "owner": fields["owner"],
                "status": status,
            }
        }
    ]


PARSERS = {"customer": parse_customers, "order": parse_orders, "note": parse_notes}


# --------------------------------------------------------------- driver ----

def collect_inputs() -> list[Path]:
    """All regular files under dropbox/, sorted by workspace-relative path."""
    return sorted(
        (p for p in DROPBOX.rglob("*") if p.is_file()),
        key=rel,
    )


def run(dry_run: bool = False) -> dict:
    records = []      # accepted normalized records in processing order
    rejects = []      # reject rows in processing order
    seen_ids = {}     # record_id -> source_path of the accepting record

    for path in collect_inputs():
        source_path = rel(path)
        suffix = path.suffix.lower()
        kind = SUPPORTED_EXTENSIONS.get(suffix)
        if kind is None:
            rejects.append(
                reject(
                    source_path,
                    "unsupported_extension",
                    f"extension '{suffix}' is not supported"
                    if suffix
                    else "file has no extension",
                )
            )
            continue

        parser = PARSERS[kind]
        try:
            results = parser(path, source_path)
        except Rejected as exc:
            rejects.append(reject(source_path, exc.error_type, exc.details))
            continue
        except Exception as exc:  # never let one bad file abort the batch
            rejects.append(
                reject(source_path, "malformed_file", f"unexpected parse error: {exc}")
            )
            continue

        for result in results:
            if "reject" in result:
                exc = result["reject"]
                rejects.append(reject(source_path, exc.error_type, exc.details))
                continue
            record = result["record"]
            record_id = record["record_id"]
            if record_id in seen_ids:
                rejects.append(
                    reject(
                        source_path,
                        "duplicate_record_id",
                        f"duplicate record_id: {record_id} "
                        f"(already accepted from {seen_ids[record_id]})",
                    )
                )
                continue
            seen_ids[record_id] = source_path
            records.append({"source_path": source_path, "record": record})

    # ---- write normalized JSON ------------------------------------------
    if not dry_run:
        if NORMALIZED.exists():
            resolved = NORMALIZED.resolve()
            if resolved != (WORKSPACE / "normalized").resolve():
                raise SystemExit(f"refusing to clear unexpected path: {resolved}")
            shutil.rmtree(NORMALIZED)
        NORMALIZED.mkdir(parents=True)

        written = set()
        for item in records:
            record = item["record"]
            filename = output_filename(record["record_type"], record["record_id"])
            if filename in written:
                raise SystemExit(f"non-unique output filename: {filename}")
            written.add(filename)
            with (NORMALIZED / filename).open("w", encoding="utf-8", newline="\n") as fh:
                json.dump(record, fh, ensure_ascii=False, indent=2, sort_keys=False)
                fh.write("\n")

        # ---- index.csv --------------------------------------------------
        index_rows = []
        for item in records:
            record = item["record"]
            index_rows.append(
                {
                    "source_path": item["source_path"],
                    "target_path": "normalized/"
                    + output_filename(record["record_type"], record["record_id"]),
                    "record_type": record["record_type"],
                    "record_id": record["record_id"],
                    "status": record["status"],
                }
            )
        # Stable sort: files ascending by source_path, records keep source order.
        index_rows.sort(key=lambda row: row["source_path"])
        write_csv(
            INDEX_PATH,
            ["source_path", "target_path", "record_type", "record_id", "status"],
            index_rows,
        )

        # ---- reject_ledger.csv -----------------------------------------
        reject_rows = sorted(rejects, key=lambda row: row["source_path"])
        write_csv(
            REJECT_PATH,
            ["source_path", "error_type", "details"],
            reject_rows,
        )

        # ---- batch_summary.json ----------------------------------------
        by_type = {"customer": 0, "order": 0, "note": 0}
        for item in records:
            by_type[item["record"]["record_type"]] += 1
        summary = {
            "success_count": len(records),
            "reject_count": len(reject_rows),
            "by_type": by_type,
        }
        with SUMMARY_PATH.open("w", encoding="utf-8", newline="\n") as fh:
            json.dump(summary, fh, ensure_ascii=False, indent=2)
            fh.write("\n")

    return {
        "records": records,
        "rejects": rejects,
        "by_type": {
            kind: sum(1 for item in records if item["record"]["record_type"] == kind)
            for kind in ("customer", "order", "note")
        },
    }


def write_csv(path: Path, header: list[str], rows: list[dict]) -> None:
    with path.open("w", encoding="utf-8", newline="") as fh:
        writer = csv.DictWriter(fh, fieldnames=header, lineterminator="\n")
        writer.writeheader()
        for row in rows:
            writer.writerow({key: row[key] for key in header})


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--dry-run", action="store_true")
    args = parser.parse_args(argv)

    if not DROPBOX.is_dir():
        print(f"error: missing input directory {DROPBOX}", file=sys.stderr)
        return 2

    outcome = run(dry_run=args.dry_run)
    summary = {
        "success_count": len(outcome["records"]),
        "reject_count": len(outcome["rejects"]),
        "by_type": outcome["by_type"],
    }
    print(json.dumps(summary, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

